var ErrInvalidConfig = errors.New("ratelimit: rate must be > 0 and burst must be >= 1")

// New creates a Limiter with the given refill rate (tokens per second)
// and burst capacity. A nil clock uses the real time.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst < 1 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		rate:     rate,
		burst:    float64(burst),
		tokens:   float64(burst), // start full
		lastTime: clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(n int) bool {
	return l.allowN(n, l.clock.Now())
}

func (l *Limiter) allowN(n int, now time.Time) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastTime = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }
