// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time
	clock  Clock

	burst int
	rate  float64 // tokens per second
}

// ErrInvalidConfig is returned by constructors for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: rate must be > 0 and burst must be >= 1")

// New creates a Limiter with the given refill rate (tokens per second)
// and burst capacity, using the real clock. The bucket starts full.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is like New but accepts an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, ErrInvalidConfig
	}
	if rate <= 0 || burst < 1 {
		return nil, ErrInvalidConfig
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
		burst:  burst,
		rate:   rate,
	}, nil
}

// AllowN reports whether n tokens may be consumed now.
// If so, it consumes them and returns true; otherwise it returns false
// and leaves the bucket unchanged.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// RetryAfter returns the duration until n tokens would become available,
// or 0 if they are available now. It does not consume tokens.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
