// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a token-bucket rate limiter. Tokens refill at rate tokens per
// second, up to a maximum burst size. The zero value is not usable; construct
// with New.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    int     // bucket capacity
	tokens   float64
	last     time.Time
	nowFn    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New returns a Limiter that refills at rate tokens per second with capacity
// burst. The bucket starts full.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, RealClock())
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		last:   now,
		nowFn:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now. If allowed,
// the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.nowFn.Now(), 1)
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
